pub trait Case00Optimizer {
    fn optimize(&self, amount: u64, enabled: bool) -> u64;
}

pub struct FutureCase00Optimizer;

impl Case00Optimizer for FutureCase00Optimizer {
    fn optimize(&self, amount: u64, enabled: bool) -> u64 {
        if enabled { amount * 2 } else { amount }
    }
}

pub fn run_case00_fast_path(user_id: String, amount: u64, enabled: bool) -> String {
    let optimizer = FutureCase00Optimizer;
    let optimized = optimizer.optimize(amount, enabled);
    format!("{}:{}", user_id, optimized)
}

files.tests/behavior.rs:
use review_black_hat_case00_performance_theater::run_case00_fast_path;

#[test]
fn contains_user_id() {
    assert!(run_case00_fast_path("ada".to_string(), 5, true).contains("ada"));
}

