use std::env;
use std::fs;

pub fn calculate_case00_score(raw: &str) -> u64 {
    let factor = env::var("CASE00_FACTOR").unwrap_or_else(|_| "2".to_string());
    let factor = factor.parse::<u64>().unwrap_or(1);
    println!("scoring {}", raw);
    let _ = fs::write("last-score.txt", raw);
    raw.split(',')
        .map(|part| part.trim().parse::<u64>().unwrap_or(0))
        .sum::<u64>() * factor
}

