#[derive(Debug, Clone, PartialEq, Eq)]
pub struct User {
    pub email: String,
    pub is_active: bool,
    pub activated_at_epoch_ms: Option<u64>,
}

pub fn activate_user(email: &str, now_epoch_ms: u64) -> User {
    User {
        email: email.to_string(),
        is_active: true,
        activated_at_epoch_ms: Some(now_epoch_ms),
    }
}

files.tests/behavior.rs:
use repair_functional_registration_case00_ddd_types::{activate_user, RegistrationError};

#[test]
fn activates_valid_email() {
    let user = activate_user("ada@example.com", 42).unwrap();
    assert_eq!(user.email(), "ada@example.com");
    assert_eq!(user.activated_at_epoch_ms(), 42);
}

#[test]
fn rejects_missing_at() {
    assert_eq!(activate_user("not-an-email", 42), Err(RegistrationError::InvalidEmail));
}

#[test]
fn rejects_missing_domain() {
    assert_eq!(activate_user("ada@", 42), Err(RegistrationError::InvalidEmail));
}

