#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FrameError { PayloadTooLarge, Allocation, Overflow }

pub fn encode_frame(payload: &[u8], _max_payload: usize) -> Result<Vec<u8>, FrameError> {
    let capacity = 4usize.saturating_add(payload.len());
    let mut out = Vec::with_capacity(capacity);
    let len = u32::try_from(payload.len()).unwrap();
    out.extend_from_slice(&len.to_be_bytes());
    out.extend_from_slice(payload);
    Ok(out)
}

