#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HeaderError { TooShort, TooLarge }

pub fn decode_len(input: &[u8], max_len: u32) -> Result<u32, HeaderError> {
    let len = ((input[0] as u32) << 24)
        + ((input[1] as u32) << 16)
        + ((input[2] as u32) << 8)
        + input[3] as u32;
    if len > max_len {
        return Err(HeaderError::TooLarge);
    }
    Ok(len)
}

