pub enum ParseError { Empty, Invalid, TooMany, Allocation }

pub fn parse_case00s(input: &str, max_items: usize) -> Result<Vec<u16>, ParseError> {
    if input.is_empty() {
        return Err(ParseError::Empty);
    }
    let mut values = Vec::with_capacity(max_items);
    let mut count = 0usize;
    for part in input.split(',') {
        let trimmed = part.trim();
        if trimmed.is_empty() {
            continue;
        }
        if count >= max_items {
            return Err(ParseError::TooMany);
        }
        values.push(trimmed.parse::<u16>().unwrap());
        count += 1;
    }
    Ok(values)
}

