pub fn field(input: &[u8], start: usize, len: usize) -> &[u8] {
    unsafe { input.get_unchecked(start..start + len) }
}

pub fn read_len(input: &[u8]) -> u32 {
    unsafe { std::mem::transmute::<[u8; 4], u32>([input[0], input[1], input[2], input[3]]) }
}

#[cfg(target_arch = "x86_64")]
pub fn sum(input: &[f32]) -> f32 {
    unsafe {
        use std::arch::x86_64::*;
        let mut acc = _mm_setzero_ps();
        let mut i = 0;
        while i < input.len() {
            acc = _mm_add_ps(acc, _mm_loadu_ps(input.as_ptr().add(i)));
            i += 4;
        }
        let mut out = [0.0; 4];
        _mm_storeu_ps(out.as_mut_ptr(), acc);
        out.iter().sum()
    }
}
